def decode_templates():
    result = {}
    for digit in range(10):
        result[digit] = []
        encoded_all = list(_TEMPLATE_PNGS_B64.get(digit, [])) + list(_GAME_FONT_TEMPLATES_B64.get(digit, []))
        for encoded in encoded_all:
            raw = base64.b64decode(encoded)
            img = cv2.imdecode(np.frombuffer(raw, dtype=np.uint8), cv2.IMREAD_GRAYSCALE)
            _, img = cv2.threshold(img, 127, 255, cv2.THRESH_BINARY)
            result[digit].append(img)
    return result


TEMPLATES = decode_templates()


def normalize_digit(binary: np.ndarray, width: int = 32, height: int = 48, pad: int = 2) -> Optional[np.ndarray]:
    ys, xs = np.nonzero(binary)
    if len(xs) == 0:
        return None

    x0, x1 = int(xs.min()), int(xs.max()) + 1
    y0, y1 = int(ys.min()), int(ys.max()) + 1
    glyph = binary[y0:y1, x0:x1]

    scale = min((width - 2 * pad) / glyph.shape[1], (height - 2 * pad) / glyph.shape[0])
    new_w = max(1, int(round(glyph.shape[1] * scale)))
    new_h = max(1, int(round(glyph.shape[0] * scale)))

    resized = cv2.resize(glyph, (new_w, new_h), interpolation=cv2.INTER_NEAREST)
    canvas = np.zeros((height, width), dtype=np.uint8)

    ox = (width - new_w) // 2
    oy = (height - new_h) // 2
    canvas[oy:oy + new_h, ox:ox + new_w] = resized
    return canvas


def iou_with_small_shifts(a: np.ndarray, b: np.ndarray) -> float:
    aa = a > 0
    bb = b > 0
    best = 0.0

    for dy in range(-2, 3):
        for dx in range(-2, 3):
            shifted = np.roll(np.roll(bb, dy, axis=0), dx, axis=1)
            inter = np.logical_and(aa, shifted).sum()
            union = np.logical_or(aa, shifted).sum()
            if union:
                best = max(best, float(inter) / float(union))

    return best


def _build_shifted_templates():
    """v10: todos os templates em todos os deslocamentos (-2..2), empilhados.

    A versao em Python puro (iou_with_small_shifts por template) custava ~75 ms
    por chamada e derrubava o loop ao vivo para ~11 fps. Vetorizado: ~2 ms.
    """
    stacks, labels = [], []
    for digit, candidates in TEMPLATES.items():
        for template in candidates:
            bb = template > 0
            for dy in range(-2, 3):
                for dx in range(-2, 3):
                    stacks.append(np.roll(np.roll(bb, dy, axis=0), dx, axis=1).ravel())
                    labels.append(digit)
    stack = np.asarray(stacks, dtype=np.float32)
    return stack, stack.sum(axis=1), np.asarray(labels, dtype=np.int32)


_SHIFTED_STACK, _SHIFTED_AREAS, _SHIFTED_LABELS = _build_shifted_templates()


def classify_digit(binary: np.ndarray):
    normalized = normalize_digit(binary)
    if normalized is None:
        return None

    glyph = (normalized > 0).ravel().astype(np.float32)
    inter = _SHIFTED_STACK @ glyph
    union = _SHIFTED_AREAS + float(glyph.sum()) - inter
    ious = np.where(union > 0, inter / np.maximum(union, 1.0), 0.0)
    scores = {}
    for digit in TEMPLATES:
        scores[digit] = float(ious[_SHIFTED_LABELS == digit].max())

    ranking = sorted(scores.items(), key=lambda item: item[1], reverse=True)
    digit, confidence = ranking[0]
    second = ranking[1][1]
    return digit, confidence, confidence - second, normalized

